// Every colour role (common or of a subject) that has a mark or a tint must have the classes a diagram paints with:
// `.st-ROLE` for strokes and `.mk-ROLE` for marks. A role with only a tint (highlight) once had neither, so a diagram
// that named it drew nothing (lesson 1069, a highlighted segment). lesson_roles.css is generated by bin/build-palette.
import "./setup.mjs"
import assert from "node:assert/strict"
import { readFileSync } from "node:fs"
import { test } from "node:test"

const palette = (await import("lesson/palette")).default
const css = readFileSync(new URL("../../../../app/assets/stylesheets/lesson_roles.css", import.meta.url), "utf8")
const rule = (selector) => css.split("\n").find((l) => l.startsWith(`${selector} {`))

const names = new Set([...Object.keys(palette.common), ...Object.values(palette.subjects).flatMap((roles) => Object.keys(roles))])

test("every role name has .st- and .mk- classes that paint", () => {
  for (const name of names) {
    assert.match(rule(`.st-${name}`) ?? "", /stroke: [^;]+;/, `.st-${name} sets a stroke`)
    assert.match(rule(`.mk-${name}`) ?? "", /fill: [^;]+;/, `.mk-${name} sets a fill`)
  }
})

test("a tint-only role is a marker pen: wide round stroke, tinted point with an outline", () => {
  const st = rule(".st-highlight")
  assert.match(st, /stroke-width: 8;/)
  assert.match(st, /stroke-linecap: round;/)
  assert.match(st, /--role-highlight-tint/)
  assert.match(st, /var\(--text\)/, "darkened toward the text colour so it reads on the surface in both themes")
  const mk = rule(".mk-highlight")
  assert.match(mk, /fill: var\(--role-highlight-tint\)/)
  assert.match(mk, /stroke: var\(--text\)/)
})
